import { AddressCopyLink } from '@cetus/design'
import { useGetToken } from '@cetus/hooks/src/useToken'
import { SingleCoinImage } from '@cetus/ui-kit'
import { imgBoxStyleProps } from '@cetus/ui-kit/src/components/SingleCoinImage'
import { Center, HStack, HTMLChakraProps, Popover, PopoverBody, PopoverContent, PopoverTrigger, Text, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'

// 没有token信息时可以只传coin_type
interface SingleTokenInfoProps extends HTMLChakraProps<'div'> {
  token?: any
  coinType?: string
  imgBoxStyle?: imgBoxStyleProps
  symbolFontSize?: string
  haveTooltip?: boolean
  haveName?: boolean
  haveSymbol?: boolean
}
const SingleTokenInfo = ({
  token,
  coinType,
  imgBoxStyle = {},
  symbolFontSize = '14px',
  haveTooltip = false,
  haveName = true,
  haveSymbol = true
}: SingleTokenInfoProps) => {
  const { getTokenInfo } = useGetToken()
  const [tokenInfo, setTokenInfo] = useState<any>(token)

  useEffect(() => {
    const fetchToken = async () => {
      if (!coinType) return
      try {
        const coinInfo = await getTokenInfo(coinType)
        setTokenInfo(coinInfo)
      } catch (error) {
        console.error('Error fetching token info:', error)
      }
    }
    fetchToken()
  }, [coinType])

  const [isShowTooltip, setIsShowTooltip] = useState(false)
  return (
    <>
      {haveTooltip ? (
        <HStack onMouseEnter={() => setIsShowTooltip(true)} onMouseLeave={() => setIsShowTooltip(false)}>
          <SingleCoinImage imageUrl={tokenInfo?.logo_url} imgBoxStyle={imgBoxStyle} />
          <VStack align="flex-start" gap="0">
            <Popover placement="right" isOpen={isShowTooltip}>
              <PopoverTrigger>
                <Center>
                  <Text color="text_caption" fontSize={symbolFontSize}>
                    {tokenInfo?.symbol}
                  </Text>
                </Center>
              </PopoverTrigger>
              <PopoverContent minW="unset" w="unset">
                <PopoverBody>
                  <AddressCopyLink address={tokenInfo?.address} showLink={false} onClickLink={() => {}} />
                </PopoverBody>
              </PopoverContent>
            </Popover>
            <Text fontSize="12px">{tokenInfo?.name}</Text>
          </VStack>
        </HStack>
      ) : (
        <HStack>
          <SingleCoinImage imageUrl={tokenInfo?.logo_url} imgBoxStyle={imgBoxStyle} />
          <VStack align="flex-start" gap="0">
            {haveSymbol && (
              <Text color="text_caption" fontSize={symbolFontSize}>
                {tokenInfo?.symbol}
              </Text>
            )}
            {haveName && <Text fontSize="12px">{tokenInfo?.name}</Text>}
          </VStack>
        </HStack>
      )}
    </>
  )
}

export default SingleTokenInfo
